    sportInitData *param = (sportInitData *)data;
#if CFG_SPORT_HYROX_BLOCK_TEMPLATE && CFG_SPORT_HYROX_TRAINING_COUNTING
    if (param != NULL && param->type == SPORT_TYPE_HYROX_TRAINING
        && param->start_type == SPORT_START_TYPE_HYROX_BLOCK
        && getSportUtils()->afterCheckThanGoToCalibration != NULL)
    {
        getSportUtils()->afterCheckThanGoToCalibration(FLAG_SCREEN_REMOVE_CURRENT, param,
                                                        param->showPhnReady);
        return;
    }
#endif
    getSportUtils()->startByFlag(param->type, FLAG_SCREEN_REMOVE_CURRENT, param->start_type);
}

