/*
    检测特定类型是否初始化过
    已初始化过返回true
    未初始化转跳初始化页面
*/
static bool _checkTypeInitialized(sportInitData *data)
{
    sportInitData *initData;
    initData = data;
    if (initData->callBack == NULL)
    {
        initData->callBack = _initSuccessCallback;
    }
    // 检查是否初始化时，先获取一下用户设置到内存中
    switch (initData->type)
    {
    case SPORT_TYPE_SWIMMING_POOL: //泳池泳道长度选择
    {
        SwimPoolLength swim = {0};
        sportSetting_getSettingManager()->poolLength->getFromFile(initData->type, &swim);
        if(swim.onOff.onOff == 0)
        {
            getScreenManager()->startScreen("SportTypeInitScreen", initData, sizeof(sportInitData));
            return false;
        }
        else
        {
            return true;
        }
    }

    case SPORT_TYPE_TENNIS:         //网球 选左右手
    case SPORT_TYPE_ROWING_MACHINE: //划船机
    case SPORT_TYPE_GOLF_SWING:     //高尔夫挥杆
    case SPORT_TYPE_OUTDOOR_ROWING: //户外划船
    case SPORT_TYPE_PADEL_PRO:      // 笼式网球 V2
    case SPORT_TYPE_SKIERG:         // 滑雪机
    case SPORT_TYPE_PICKLEBALL_PRO: // 匹克球（带挥拍）
    {
        SportSettingTypeChoice choice = {0};
        sportSetting_getSettingManager()->wearHand->getFromFile(initData->type, &choice);
        if (choice.choice == 0)
        {
            getScreenManager()->startScreen("SportSettingWearHandScreen", initData, sizeof(sportInitData));
            return false;
        }
        else
        {
            return true;
        }
    }
#if CFG_SPORT_SUPPORT_INDOORCLIMBING
    case SPORT_TYPE_BOULDERING:    //抱石
    case SPORT_TYPE_INDOOR_CLIMBING:  //室内攀岩
    {
        char *screenName = getScreenManager()->getCurrentScreenName();
        if (strcmp(screenName,"SportSettingClimbScreen") != 0)
        {
            getScreenManager()->startScreen("SportSettingClimbScreen", initData, sizeof(sportInitData));
            return false;
        }
        else
        {
            return true;
        }
    }
#endif

#if SPORT_TREADMILL_CONSTANT_SPEED_MODE
    case SPORT_TYPE_TREADMILL: //跑步机
    {
        char *screenName = getScreenManager()->getCurrentScreenName();
        sport_setting_treadmill_t treadmill_setting = {0};
        sportSetting_getOps()->get(SPORT_SETTING_TYPE_TREADMILL, &treadmill_setting);
        /* 自识别的方式，默认自由模式，无需选择模式 */
        /* 已经选择了模式，需要跳转readyGo */
        if (!treadmill_setting.mode_finish && strcmp(screenName,"Settings_exerRecgTypeScreen") != 0)
        {
            getScreenManager()->startScreen("SportSettingTreadmillModeScreen", initData, sizeof(sportInitData));
            return false;
        }
        else
        {
            return true;
        }
    }
#endif
#ifdef CFG_SPORT_MULTISPORT_INIT
    case SPORT_TYPE_MULTISPORT: //复合运动
    {
        /*  检查是否第一次开启复合运动  */
        if(sportSetting_getSettingManager()->sportFirstStart->get(SPORT_TYPE_MULTISPORT))
        {
            getScreenManager()->startScreenByFlag("SportInitMultisportScreen",FLAG_SCREEN_STANDAR,initData,sizeof(sportInitData));
            return false;
        }
        else
        {
            return true;
        }
    }
#endif
#if CFG_SPORT_SUPPORT_HYROX
    case SPORT_TYPE_HYROX_RACE: //Hyrox race
    {
        char *screenName = getScreenManager()->getCurrentScreenName();
        bool fromHyroxTypeInit = (strcmp(screenName, "SportTypeInitItemSelectScreen") == 0);
#if CFG_SPORT_SUPPORT_RACE_STRATEGY
        /* 仅在首次初始化流程判断一次比赛策略是否存在；从类型初始化页回调再次进入时直接放行 */
        if (!fromHyroxTypeInit && checkSportStrategysExist(initData->type))
        {
            getScreenManager()->startScreen("SportStrategyChoiceScreen", initData, sizeof(sportInitData));
            return false;
        }
#endif

        if (!fromHyroxTypeInit)
        {
            /* 首次进入后先进单/双人/团体赛，再进入phn */
            getScreenManager()->startScreen("SportTypeInitItemSelectScreen", initData, sizeof(sportInitData));
            return false;
        }

        return true;
    }
    case SPORT_TYPE_HYROX_PFT:
    {
        getSportSaveHyroxManager()->setHyroxPftCheckCfg();
        if (getSportSaveHyroxManager()->getShowBackHinted() == false)
        {
            getScreenManager()->startScreen("SportCustomBackHintScreen", initData, sizeof(sportInitData));
            return false;
        }
        return true;
    }
    case SPORT_TYPE_HYROX_SIMULATION:
    {
        char *screenName = getScreenManager()->getCurrentScreenName();
        if (strcmp(screenName,"hyroxSimulateChooseScreen") != 0)
        {
            getScreenManager()->startScreen("hyroxSimulateChooseScreen", initData, sizeof(sportInitData));
            return false;
        }
        else
        {
            return true;
        }
    }
#endif
#if CFG_SPORT_SUPPORT_SKI_MOUNTAIN
    case SPORT_TYPE_SKI_MOUNTAINEERING:
    {
        SportSettingChangeMode initMod = {0};
        sportSetting_getSettingManager()->skiModeInit->getFromFile(initData->type, &initMod);
        if (initMod.onOff.onOff == 0)
        {
            getScreenManager()->startScreen("SportSettingSkiMountModeScreen", initData, sizeof(sportInitData));
            return false;
        }
        else
        {
            return true;
        }
    }
#endif
    case SPORT_TYPE_RUCKING:
    {
        SportSettingsMessage *cfg = H_MALLOC(sizeof(SportSettingsMessage));
        if (cfg == NULL)
        {
            HLOG_E("RUCKING", "%s,inithr malloc for cfg failed", __func__);
            return false;
        }

        sportSetting_getSettingManager()->getFromFillSetting(SPORT_TYPE_RUCKING, cfg);

        if(cfg->assist.RuckingSetting.onOff == 0)
        {
            int pickerID = PICKER_ID_RUCKING_WEIGHT;
            getScreenManager()->startScreen("SportPickerScreen", &pickerID, sizeof(int));
            H_FREE(cfg);
            return false;
        }
        else
        {
            H_FREE(cfg);
            return true;
        }
    }
    case SPORT_TYPE_RUNNING_TRACK:
    {
#ifdef CFG_SPORT_SUPPORT_CALENDAR
        // 只有训练日历里的模板需要在本函数判断，普通开启方式在go页面内部判断
        if (initData != NULL && initData->invoked == INVOCKED_FROM_CALENDAR)
        {
            SportSettingsMessage *setting = H_MALLOC(sizeof(SportSettingsMessage));
            if (setting == NULL)
            {
                HLOG_E(TAG, "%s, malloc setting failed", __func__);
                return false;
            }
            sportSetting_getSettingManager()->getFromFillSetting(initData->type, setting);
            uint32_t choice = setting->more.playground.distance.choice;
            if (setting != NULL)
            {
                H_FREE(setting);
                setting = NULL;
            }

            if (choice == 0)
            {
                getScreenManager()->startScreenByFlag("SportFirstPgDistanceScreen", FLAG_SCREEN_NO_HISTORY, initData, sizeof(sportInitData));
                return false;
            }
        }
#endif
        return true;
    }
    default:
        return true;
    }

}

