static bool checkIsFromPHN()
{
#if (CFG_SUPPORT_LAUNCHER_VERSION == 1)
    ScreenStackManager *screenStackManager = getScreenStackManager();
    if (!screenStackManager)
    {
        HLOG_E(TAG, "%s  screenStackManager = NULL", __func__);
        return false;
    }
    // 获取页面栈
    ScreenStack *pStack = screenStackManager->peekScreenStack();
    for (; pStack != NULL;)
    {
        HLOG_D(TAG, "%s  screenName = %s", __func__,pStack->pInfo->screenName);
        // 如果栈内有phnScreen,说明是phn进入运动列表
        if (strcmp(pStack->pInfo->screenName, "PhnScreen") == 0)
        {
            return true;
        }
        pStack = pStack->pNext;
    }
    return false;
#elif (CFG_SUPPORT_LAUNCHER_VERSION == 2)
    return getIsFromPhnflag();
#endif
}
