static void gotoPhnOrNormalReady(ScreenFlag flag, sportInitData *initData, bool showPhnReady)
{
    if (showPhnReady)
    {
        getScreenManager()->startScreenByFlag("PhnReadygoScreen", flag, NULL, 0);
    }
#if CFG_SPORT_HYROX_BLOCK_TEMPLATE && CFG_SPORT_HYROX_TRAINING_COUNTING
