    else
    {
        getScreenManager()->startScreenByFlag("SportReadyGoScreen", flag, initData, sizeof(sportInitData));
    }
}

/**
 * @brief 检查后根据运动类型调整到算法校准
 * @param flag 屏幕跳转模式（压栈不压栈等）
 * @param initData 初始化数据
 * @param showPhnReady 是否显示phn readygo screen
 */
static void _afterCheckThanGoToCalibration(ScreenFlag flag, sportInitData *initData, bool showPhnReady)
{
    if (initData == NULL)
    {
        return;
    }

#if (CFG_SPORT_HYROX_BLOCK_TEMPLATE && CFG_SPORT_HYROX_TRAINING_COUNTING) || CFG_SPORT_SUPPORT_HYROX_SIMULATION
    switch (initData->type)
    {
#if CFG_SPORT_HYROX_BLOCK_TEMPLATE && CFG_SPORT_HYROX_TRAINING_COUNTING
        case SPORT_TYPE_HYROX_TRAINING:
        {
            if (SportContrlService_getOps()->getStartType() != SPORT_START_TYPE_HYROX_BLOCK)
            {
                break;
            }
            if (!hasAutoCountingActionInHyroxTraining(initData->templatePath))
            {
                hyroxTraining_setAutoCountingEnabled(false);
                /* 无自动计次动作的 block 模板直接进入 ReadyGo。 */
                break;
            }
            hyroxTraining_setAutoCountingEnabled(true);
#if CFG_SPORT_SUPPORT_HYROX_SIMULATION
            if (initData->invoked != INVOCKED_FROM_CALENDAR &&
                getSportSaveHyroxManager()->getHyroxSensorConnectState() >= 0)
            {
                /* 已绑定 HSP 的自动计次模板进入连接/校准流程。 */
                initData->showPhnReady = showPhnReady;
                getScreenManager()->startScreenByFlag("hyroxSimConnectScreen", flag,
                                                       initData, sizeof(sportInitData));
                return;
            }
#endif
            /* 日历入口不进入校准；其余未绑定或未连接 HSP 的场景均选择左右手。 */
            initData->showPhnReady = showPhnReady;
            initData->callBack = _hyroxBlockWearHandSelectedCallback;
            getScreenManager()->startScreen("SportSettingWearHandScreen", initData,
                                            sizeof(sportInitData));
            return;
        }
#endif
#if CFG_SPORT_SUPPORT_HYROX_SIMULATION
        case SPORT_TYPE_HYROX_RACE:
        case SPORT_TYPE_HYROX_SIMULATION:
        {
            int32_t conneted = getSportSaveHyroxManager()->getHyroxSensorConnectState();
            if (conneted < 0)
            {
                gotoPhnOrNormalReady(flag, initData, showPhnReady);
            }
            else
            {
                initData->showPhnReady = showPhnReady;
                /* 已连接 HSP 时先到 ReadyGo；点击 GO 后再按 HSP 版本能力
                 * 选择动态校准或旧版静态校准流程。版本无法确认时必须走静态校准。 */
                if (getSportSaveHyroxManager()->hyroxSupportAutoCalibration(initData->type))
                {
                    gotoPhnOrNormalReady(flag, initData, showPhnReady);
                }
                else
                {
                    getScreenManager()->startScreenByFlag("hyroxSimConnectScreen", FLAG_SCREEN_STANDAR,
                                                         initData, sizeof(sportInitData));
                }
            }
            return;
        }
#endif
        default:
            break;
    }
#endif
    gotoPhnOrNormalReady(flag, initData,showPhnReady);
}
