    }
    getSportSaveHyroxManager()->handleHyroxServiceMessge(HYROX_SERVICE_MESSAGE_BEGIN);
    getScreenManager()->startScreenByFlag("hyroxSensorChooseScreen", FLAG_SCREEN_STANDAR, &appData->initData, sizeof(sportInitData));
}

static AlertDialog *getShowingDialog(ScreenContext *mContext)
{
    AlertDialog *mDialog = (AlertDialog *)findContainer(mContext, HYROX_FIRST_CONNECT_DIALOG);
    if (mDialog && mDialog->isShowing(mDialog))
    {
        return mDialog;
    }

    mDialog = (AlertDialog *)findContainer(mContext, HYROX_GOTO_CALIBARETE_DIALOG);
    if (mDialog && mDialog->isShowing(mDialog))
    {
        return mDialog;
    }

    return NULL;
}

static void dismissDialog(ScreenContext *mContext, const char *id)
{
    AlertDialog *mDialog = (AlertDialog *)findContainer(mContext, id);
    if (mDialog && mDialog->isShowing(mDialog))
    {
        mDialog->dismissDialog(mDialog);
    }
}

static void finishNoUserScreen(AppData *appData)
{
    if (appData == NULL)
