static void chooseWhichReadyGo(ScreenContext *mContext)
{
    AppData *appData = getScreenData(mContext, AppData);
    if (appData == NULL)
    {
        HLOG_E(TAG, "%s appData error", __func__);
        return;
    }
    finishNoUserScreen(appData);
    uint8_t flag = FLAG_SCREEN_REMOVE_CURRENT;
    switch (appData->initData.start_type)
    {
        case SPORT_START_TYPE_PHN:
        case SPORT_START_TYPE_PHN_RUNNING:
        {
            if (appData->initData.showPhnReady)
            {
                getScreenManager()->startScreenByFlag("PhnReadygoScreen", flag, NULL, 0);
