            return;
        }
        case SPORT_START_TYPE_RACE_STRATEGY:
            getScreenManager()->startScreenByFlag("SportHyroxRaceStrategyScreen", flag, &appData->initData, sizeof(sportInitData));
            return;
#if CFG_SPORT_HYROX_BLOCK_TEMPLATE && CFG_SPORT_HYROX_TRAINING_COUNTING
