            getScreenManager()->startScreenByFlag("SportTrainingScreen", flag,
                                                   &appData->initData, sizeof(sportInitData));
            return;
#endif
        default:
            break;
    }
    getScreenManager()->startScreenByFlag("SportReadyGoScreen", flag, &appData->initData, sizeof(sportInitData));
}

