static int normalizeProgress(int progress)
{
    if (progress < 0)
    {
        return 0;
    }
    if (progress > HYROX_REGRET_ALL_PROGRESS)
    {
        return HYROX_REGRET_ALL_PROGRESS;
    }
    return progress;
}

static void updateProgressBar(int progress)
{
    int normalizedProgress = normalizeProgress(progress);
#ifndef HM_DISPLAY_IS_ROUND
    gre_control_rectangle_set_progress(getAppInstance(), PROGRESS_BAR_RECT_PATH,
                                       (normalizedProgress * 100.0f) / HYROX_REGRET_ALL_PROGRESS);
    gre_post_redraw(getAppInstance());
#else
    setSBIntData(getAppInstance(), PROGRESS_BAR_PROGRESS_PATH, normalizedProgress);
#endif
}

static void updateCountdownView(AppData *appData)
{
    if (!appData)
    {
        return;
    }

    int elapsedSeconds = (appData->elapsedMs + HYROX_SECOND - 1) / HYROX_SECOND;
    if (elapsedSeconds >= COUNTDOWN_TOTAL_SECONDS ||
        appData->calibrateState == HYROX_SIMULATION_CALIB_SUCCESS)
    {
        appData->countdownSeconds = 0;
        appData->progress = 0;
        appData->isCountdownFinished = true;
    }
    else
    {
        appData->isCountdownFinished = false;
        appData->countdownSeconds = COUNTDOWN_TOTAL_SECONDS - elapsedSeconds;
        appData->progress = normalizeProgress(HYROX_REGRET_ALL_PROGRESS - elapsedSeconds * HYROX_REGRET_PRE_PROGRESS);
    }

    char buffer[32] = {0};
    hm_snprintf(buffer, sizeof(buffer), "%d", appData->countdownSeconds);
    gre_direct_set_text_string_by_idx(getAppInstance(), COUNTDOWN_TEXT_PATH, buffer, 0);
    updateProgressBar(appData->progress);
}

