/**
 * @brief 定时器回调函数
 * @param timer 定时器句柄
 * @param data 用户数据
 * @param dropped 丢弃次数
 * @return 0 继续定时器，非 0 停止定时器
 */
static bool handleCountdownTimerTick(EventData *eventData)
{
    ScreenContext *mContext = getScreenContext(getScreen(SCREEN_NAME));
    AppData *appData = getScreenData(mContext, AppData);
    if (!appData)
    {
        return true;
    }

    // 增加计数（从 0 开始递增，每 500ms 触发一次）
    appData->elapsedMs += COUNTDOWN_INTERVAL_MS;

    // 计算已经过去的秒数（向上取整，确保显示准确）
    int elapsedSeconds = (appData->elapsedMs + 999) / HYROX_SECOND;

    HLOG_D(TAG, "%s elapsedMs: %d, elapsedSeconds: %d", __func__,
           appData->elapsedMs, elapsedSeconds);

    appData->calibrateState = getSportSaveHyroxManager()->getHyroxSimCalibrateState();
    if (appData->calibrateState == HYROX_SIMULATION_CALIB_SUCCESS)
    {
        appData->countdownSeconds = 0;
        appData->progress = 0;
        appData->isCountdownFinished = true;

        char buffer[32] = {0};
        hm_snprintf(buffer, sizeof(buffer), "%d", 0);
        gre_direct_set_text_string_by_idx(getAppInstance(), COUNTDOWN_TEXT_PATH, buffer, 0);
        updateProgressBar(0);

        HLOG_I(TAG, "%s calibrate success!", __func__);

        if (appData->timerHandle)
        {
            hmTime_stopTimer(appData->timerHandle);
        }

        createSensorDialog();
        doVibrate();
        return true;
    }

    // 判断是否结束（超过 10 秒）
    if (elapsedSeconds >= COUNTDOWN_TOTAL_SECONDS)
    {
        // 倒计时结束
        appData->countdownSeconds = 0;
        appData->progress = 0;  // 进度归零
        appData->isCountdownFinished = true;

        // 更新 UI 显示 - 显示 0
        char buffer[32] = {0};
        hm_snprintf(buffer, sizeof(buffer), "%d", 0);
        gre_direct_set_text_string_by_idx(getAppInstance(), COUNTDOWN_TEXT_PATH, buffer, 0);
        updateProgressBar(0);

        HLOG_I(TAG, "%s countdown finished!", __func__);

        // 停止定时器
        if (appData->timerHandle)
        {
            hmTime_stopTimer(appData->timerHandle);
        }

        createSensorDialog();
        doVibrate();
        return true;
    }

    // 更新剩余秒数显示（从 10 递减到 0）
    appData->countdownSeconds = COUNTDOWN_TOTAL_SECONDS - elapsedSeconds;

    // 更新进度条进度值（从 360 递减到 0）
    // 参考 _handleCountDownEvent: 360 - startTime * 36
    appData->progress = normalizeProgress(HYROX_REGRET_ALL_PROGRESS - elapsedSeconds * HYROX_REGRET_PRE_PROGRESS);

    HLOG_D(TAG, "%s countdown: %ds, progress: %d", __func__,
           appData->countdownSeconds, appData->progress);

    // 更新 UI 显示
    char buffer[32] = {0};
    hm_snprintf(buffer, sizeof(buffer), "%d", appData->countdownSeconds);
    gre_direct_set_text_string_by_idx(getAppInstance(), COUNTDOWN_TEXT_PATH, buffer, 0);
    updateProgressBar(appData->progress);

    return true;
}

static void countdownTimerCallback(TimerHandle time)
{
    message_sendEventDirect(getUIHandle(), NULL, handleCountdownTimerTick);
}

static void createCancelTimer(AppData *appData, uint32_t timeoutMs, bool resetStartTime)
{
    if (appData == NULL)
    {
        HLOG_E(TAG, "%s appData is NULL", __func__);
        return;
    }

    destroyCancelTimer(appData);
    appData->cancelTimerHandle = hmTime_createTimerWithName(HM_TIMER_ONCE,
        cancelTimerCallback, "hyrox_calibrate_cancel_timer", H_NULL);
    if (appData->cancelTimerHandle == NULL)
    {
        HLOG_E(TAG, "%s create timer failed!", __func__);
        return;
    }

    if (resetStartTime)
    {
        HmTime mTime = {0};
        hmTime_getTime(&mTime);
        appData->startTime = mTime.sec;
    }

    if (!hmTime_startTimer(appData->cancelTimerHandle, timeoutMs))
    {
        HLOG_E(TAG, "%s start timer failed!", __func__);
    }
}

static void destroyCancelTimer(AppData *appData)
{
    if (appData == NULL || appData->cancelTimerHandle == NULL)
    {
        return;
    }

    hmTime_stopTimer(appData->cancelTimerHandle);
    hmTime_destroyTimer(appData->cancelTimerHandle);
    appData->cancelTimerHandle = H_NULL;
}

/**
 * @brief 创建并启动倒计时定时器
 * @param screenContext 屏幕上下文
 */
static void createCountdownTimer(ScreenContext *screenContext, bool isResume)
{
    if (!screenContext)
    {
        HLOG_E(TAG, "%s screenContext is NULL", __func__);
        return;
    }

    AppData *appData = getScreenData(screenContext, AppData);
    if (!appData)
    {
        HLOG_E(TAG, "%s appData is NULL", __func__);
        return;
    }

    // 清除旧的定时器
    if (appData->timerHandle)
    {
        hmTime_stopTimer(appData->timerHandle);
    }

    // 【关键修改】只有在非恢复模式下才重置数据
    if (!isResume)
    {
        appData->countdownSeconds = COUNTDOWN_TOTAL_SECONDS;
        appData->progress = HYROX_REGRET_ALL_PROGRESS;
        appData->elapsedMs = 0;
        appData->isCountdownFinished = false;
        appData->isRestored = false;
        // 立即更新 UI 显示初始状态
        char buffer[32] = {0};
        hm_snprintf(buffer, sizeof(buffer), "%d", appData->countdownSeconds);
        gre_direct_set_text_string_by_idx(getAppInstance(), COUNTDOWN_TEXT_PATH, buffer, 0);
        updateProgressBar(appData->progress);

        HLOG_I(TAG, "%s Start new timer, total: %ds", __func__, COUNTDOWN_TOTAL_SECONDS);
    }
    else
    {
        // 恢复模式：UI 已经在 onDataRestore 中更新过了，这里只需要确保数据一致性
        // 计算当前的 progress 以防万一
        int elapsedSeconds = (appData->elapsedMs + 999) / HYROX_SECOND;
        if (elapsedSeconds >= COUNTDOWN_TOTAL_SECONDS)
        {
             // 如果恢复时发现已经超时，直接结束
             appData->countdownSeconds = 0;
             appData->progress = 0;
             appData->isCountdownFinished = true;

             char buffer[32] = {0};
             hm_snprintf(buffer, sizeof(buffer), "%d", 0);
             gre_direct_set_text_string_by_idx(getAppInstance(), COUNTDOWN_TEXT_PATH, buffer, 0);
             updateProgressBar(0);

             createSensorDialog();
             doVibrate();
             return;
        }

        // 更新进度条进度
        appData->progress = normalizeProgress(HYROX_REGRET_ALL_PROGRESS - elapsedSeconds * HYROX_REGRET_PRE_PROGRESS);
        HLOG_I(TAG, "%s Resume timer, elapsed: %dms, left: %ds", __func__,
               appData->elapsedMs, appData->countdownSeconds);
    }

    if (appData->timerHandle == NULL)
    {
        appData->timerHandle = hmTime_createTimerWithName(HM_TIMER_PERIODIC,
            countdownTimerCallback, "hyrox_calibrate_timer", H_NULL);
    }

    if (appData->timerHandle == NULL)
    {
        HLOG_E(TAG, "%s create timer failed!", __func__);
        return;
    }

    if (!hmTime_startTimer(appData->timerHandle, COUNTDOWN_INTERVAL_MS))
    {
        HLOG_E(TAG, "%s start timer failed!", __func__);
    }
}

/**
 * @brief 销毁定时器
 * @param appData App 数据指针
 */
static void destroyTimer(AppData *appData)
{
    if (appData && appData->timerHandle)
    {
        hmTime_stopTimer(appData->timerHandle);
        hmTime_destroyTimer(appData->timerHandle);
        appData->timerHandle = H_NULL;
    }
}

/**
 * @brief 屏幕预创建回调
 */
static void onScreenPreCreate(ScreenContext *screenContext, void *data)
{
    AppData *appData = (AppData *)H_MALLOC(sizeof(AppData));
    if (!appData)
    {
        HLOG_E(TAG, "%s malloc failed", __func__);
        return;
    }

    memset(appData, 0, sizeof(AppData));
    appData->countdownSeconds = COUNTDOWN_TOTAL_SECONDS;
    appData->progress = HYROX_REGRET_ALL_PROGRESS;
    appData->elapsedMs = 0;
    appData->timerHandle = NULL;
    appData->cancelTimerHandle = NULL;
    appData->isCountdownFinished = false;
    appData->isRestored = false;
    appData->calibrateState = HYROX_SIMULATION_CALIB_UNDONE;
    setScreenData(screenContext, appData);

#ifndef HM_DISPLAY_IS_ROUND
    // 方屏设置状态栏标题
    HmSysStatusBar_setVisible(H_False);
    gre_control_rectangle_to_progress(getAppInstance(), PROGRESS_BAR_RECT_PATH, 2);
#endif
    char buffer[32] = {0};
    hm_snprintf(buffer, sizeof(buffer), "%d", 10);
    gre_direct_set_text_string_by_idx(getAppInstance(), COUNTDOWN_TEXT_PATH, buffer, 0);
    updateProgressBar(HYROX_REGRET_ALL_PROGRESS);
    if (data)
    {
        memcpy(&appData->initData, data, sizeof(sportInitData));
    }
    getSportSaveHyroxManager()->hyroxSensorAutoConnect(true);
    createCancelTimer(appData, HYROX_CANCEL_TIMEOUT_MS, true);
}

/**
 * @brief 数据恢复回调 (息屏后恢复)
 */
static void onDataRestore(ScreenContext *screenContext, void *data)
{
    if (!data)
    {
        HLOG_W(TAG, "%s no save data", __func__);
        return;
    }

    SaveData *saveData = (SaveData *)data;
    AppData *appData = getScreenData(screenContext, AppData);

    if (!appData)
    {
        HLOG_E(TAG, "%s appData is NULL", __func__);
        return;
    }
    memcpy(&appData->initData, &saveData->initData, sizeof(sportInitData));

    uint64_t nowMs = getUtcMs();
    uint64_t sleepElapsedMs = 0;
    if (saveData->saveTimestampMs > 0 && nowMs > saveData->saveTimestampMs)
    {
        sleepElapsedMs = nowMs - saveData->saveTimestampMs;
    }

    uint64_t restoredElapsedMs = (uint64_t)saveData->elapsedMs + sleepElapsedMs;
    if (restoredElapsedMs > COUNTDOWN_TOTAL_SECONDS * HYROX_SECOND)
    {
        appData->elapsedMs = COUNTDOWN_TOTAL_SECONDS * HYROX_SECOND;
    }
    else
    {
        appData->elapsedMs = (int)restoredElapsedMs;
    }
    appData->isCountdownFinished = saveData->isCountdownFinished;
    appData->isRestored = true;
    appData->calibrateState = saveData->calibrateState;
    appData->startTime = saveData->startTime;

    if (appData->startTime > 0)
    {
        HmTime mTime = {0};
        hmTime_getTime(&mTime);
        int32_t duration = (int32_t)(mTime.sec - appData->startTime);
        if (duration >= 0 && duration < HYROX_WAKE_LOCK_SEC)
        {
            createCancelTimer(appData, (HYROX_WAKE_LOCK_SEC - duration) * HYROX_SECOND, false);
        }
        else
        {
            destroyCancelTimer(appData);
            getSportSaveHyroxManager()->handleHyroxServiceMessge(HYROX_SERVICE_MESSAGE_CANCLE);
            return;
        }
    }
    else
    {
        createCancelTimer(appData, HYROX_CANCEL_TIMEOUT_MS, true);
    }

    // 根据恢复的状态更新 UI
    updateCountdownView(appData);

    HLOG_I(TAG, "%s savedElapsed: %d, sleepElapsed: %llu, restoredElapsed: %d",
           __func__, saveData->elapsedMs, (unsigned long long)sleepElapsedMs, appData->elapsedMs);

    // 【关键修改】重新启动定时器，传入 true 表示是恢复场景，不要重置时间
    if (appData->countdownSeconds > 0 && !appData->isCountdownFinished)
    {
        createCountdownTimer(screenContext, true);
    }
    else
    {
        // 如果恢复时已经倒计时结束，直接显示对话框
        createSensorDialog();
    }
}

/**
 * @brief 数据保存回调 (息屏前保存)
 * @param screenContext 屏幕上下文
 */
static void onDataSave(ScreenContext *screenContext)
{
    HLOG_D(TAG, "%s", __func__);

    AppData *appData = getScreenData(screenContext, AppData);
    if (!appData)
    {
        HLOG_E(TAG, "%s appData is NULL", __func__);
        return;
    }
    SaveData saveData = {0};
    saveData.countdownSeconds = appData->countdownSeconds;
    saveData.progress = appData->progress;
    saveData.elapsedMs = appData->elapsedMs;
    saveData.saveTimestampMs = getUtcMs();
    saveData.isCountdownFinished = appData->isCountdownFinished;
    saveData.calibrateState = appData->calibrateState;
    saveData.startTime = appData->startTime;
    memcpy(&saveData.initData, &appData->initData, sizeof(sportInitData));
    getScreenManager()->saveScreenData(getScreen(SCREEN_NAME)->id, &saveData, sizeof(SaveData));
}

/**
 * @brief 屏幕后创建回调
 * @param screenContext 屏幕上下文
 */
static void onScreenPostCreate(ScreenContext *screenContext)
{
    HLOG_I(TAG, "%s", __func__);
    System_enableGoDefaultScreen(H_False);

    AppData *appData = getScreenData(screenContext, AppData);
    lockCalibrateWakeLock(appData);
    System_setKeyFilter(HM_KEY_CODE_BACK, HM_KEY_ACTION_LONG_PRESS | HM_KEY_ACTION_CLICK);
    System_setKeyFilter(HM_KEY_CODE_SHORTCUT, HM_KEY_ACTION_LONG_PRESS | HM_KEY_ACTION_CLICK);
    if (appData && appData->isRestored)
    {
        HLOG_I(TAG, "%s restored screen, skip new countdown", __func__);
        return;
    }

    createCountdownTimer(screenContext, false);
}

/**
 * @brief 屏幕预销毁回调
 * @param screenContext 屏幕上下文
 */
static void onScreenPreDestory(ScreenContext *screenContext)
{
    System_enableGoDefaultScreen(H_True);
    AppData *appData = getScreenData(screenContext, AppData);
    if (appData)
    {
        destroyCancelTimer(appData);
        unlockCalibrateWakeLock(appData);
        destroyTimer(appData);
    }
    getSportSaveHyroxManager()->hyroxSensorAutoConnect(false);
    System_resetKeyFilter(HM_KEY_CODE_BACK);
    System_resetKeyFilter(HM_KEY_CODE_SHORTCUT);
}

