 */
static bool handleTouchEvent(ScreenContext *screenContext, const char *id,
                            const SBTouchEvent eventId, const SBEventInfo *info)
{
    AlertDialog *mConfirmDialog = (AlertDialog *)findContainer(screenContext, HYROX_SIMU_CALIBRATE_DIALOG);
    if (mConfirmDialog && mConfirmDialog->isShowing(mConfirmDialog))
    {
        return mConfirmDialog->container.handleTouchEvent(screenContext, &mConfirmDialog->container, id, eventId, info);
    }
    return false;
}

/**
 * @brief 按键事件处理
 */
static bool handleKeyEvent(ScreenContext *screenContext, const HmKeyEvent *info)
{
    if (info->code == HM_KEY_CODE_BACK || info->code == HM_KEY_CODE_SHORTCUT)
    {
        if (info->action == HM_KEY_ACTION_CLICK)
        {
            gotoSensorChooseScreen(screenContext);
        }
        else if (info->action == HM_KEY_ACTION_LONG_PRESS)
        {
            backToHomeWithCancel();
        }
        return true;
    }
    AlertDialog *mConfirmDialog = (AlertDialog *)findContainer(screenContext, HYROX_SIMU_CALIBRATE_DIALOG);
    if (mConfirmDialog && mConfirmDialog->isShowing(mConfirmDialog))
    {
        return mConfirmDialog->container.handleKeyEvent(screenContext, &mConfirmDialog->container, info);
    }
    return false;
}

/**
 * @brief 手势事件处理
 */
static bool handleGestureEvent(ScreenContext *screenContext, const char* id, const SBGestureEvent eventId)
{
    if (GESTURE_RIGHT == eventId) // 右滑动
    {
        gotoSensorChooseScreen(screenContext);
    }
    return false;
}

/**
 * @brief 通用事件处理
 */
