extern void ScreenManager_setHomeScreen(const char *screenName);

SCREEN_DECLARE(SCREEN_NAME);

static void createFirstConnectStrapDialog(ScreenContext *mContext);
static void createGotoCalibareteDialog(ScreenContext *mContext);

typedef struct
{
    TimerHandle cancelTimerHandle;
    WakeLockHandle wakeLockHandle;
    bool hasShownCalibrateDialog;
    uint32_t startTime;
    sportInitData initData;         // 运动初始化信息
} AppData;

static void destroyCancelTimer(AppData *appData);
static void backToHomeWithCancel(void);
static void chooseWhichReadyGo(ScreenContext *mContext);

static void handleConnectedSensor(ScreenContext *mContext, AppData *appData)
{
    if (getSportSaveHyroxManager()->hyroxSupportAutoCalibration(appData->initData.type))
    {
        destroyCancelTimer(appData);
        chooseWhichReadyGo(mContext);
        return;
    }

    createGotoCalibareteDialog(mContext);
    appData->hasShownCalibrateDialog = true;
}

static bool handleCancelTimerTick(EventData *eventData)
{
    (void)eventData;
    ScreenContext *mContext = getScreenContext(getScreen(SCREEN_NAME));
    if (mContext == NULL)
    {
        return true;
    }

    AppData *appData = getScreenData(mContext, AppData);
    if (appData == NULL)
    {
        return true;
    }

    int32_t connected = getSportSaveHyroxManager()->getHyroxSensorConnectState();
    if (connected > 0)
    {
        if (!appData->hasShownCalibrateDialog)
        {
            handleConnectedSensor(mContext, appData);
            return true;
        }
    }

    HmTime mTime = {0};
    hmTime_getTime(&mTime);
    int32_t duration = (int32_t)(mTime.sec - appData->startTime);
    if (duration >= HYROX_WAKE_LOCK_SEC)
    {
        destroyCancelTimer(appData);
        backToHomeWithCancel();
    }

    return true;
}

static void cancelTimerCallback(TimerHandle time)
{
    (void)time;
    message_sendEventDirect(getUIHandle(), NULL, handleCancelTimerTick);
}

static void lockConnectWakeLock(AppData *appData)
{
    if (appData == NULL)
    {
        return;
    }

    if (appData->wakeLockHandle != 0)
    {
        getPowerManager()->release(appData->wakeLockHandle);
        appData->wakeLockHandle = 0;
    }

    appData->wakeLockHandle = getPowerManager()->acquireWithTimeout(
        SCREEN_NAME_FULL,
        SCREEN_BRIGHT_WAKE_LOCK | ON_AFTER_RELEASE | DENY_SCREEN_OFF_WHEN_PLAM,
        HYROX_WAKE_LOCK_SEC);
}

static void unlockConnectWakeLock(AppData *appData)
{
    if (appData == NULL || appData->wakeLockHandle == 0)
    {
        return;
    }

    getPowerManager()->release(appData->wakeLockHandle);
    appData->wakeLockHandle = 0;
}

static void createCancelTimer(ScreenContext *mContext, AppData *appData, bool resetStartTime)
{
    if (mContext == NULL || appData == NULL)
    {
        HLOG_E(TAG, "%s param null", __func__);
        return;
    }

    destroyCancelTimer(appData);
    if (resetStartTime)
    {
        HmTime mTime = {0};
        hmTime_getTime(&mTime);
        appData->startTime = mTime.sec;
    }

    int32_t connected = getSportSaveHyroxManager()->getHyroxSensorConnectState();
    if (connected > 0)
    {
        handleConnectedSensor(mContext, appData);
        return;
    }
    else
    {
        createFirstConnectStrapDialog(mContext);
    }

    HmTime mTime = {0};
    hmTime_getTime(&mTime);
    int32_t duration = (int32_t)(mTime.sec - appData->startTime);
    if (duration >= HYROX_WAKE_LOCK_SEC)
    {
        getSportSaveHyroxManager()->handleHyroxServiceMessge(HYROX_SERVICE_MESSAGE_CANCLE);
        return;
    }

    appData->cancelTimerHandle = hmTime_createTimerWithName(HM_TIMER_PERIODIC,
        cancelTimerCallback, "hyrox_first_connect_cancel_timer", H_NULL);
    if (appData->cancelTimerHandle == NULL)
    {
        HLOG_E(TAG, "%s create timer fail", __func__);
        return;
    }

    if (!hmTime_startTimer(appData->cancelTimerHandle, HYROX_CONNECT_POLL_INTERVAL_MS))
    {
        HLOG_E(TAG, "%s start timer fail", __func__);
    }
}

static void destroyCancelTimer(AppData *appData)
{
    if (appData == NULL || appData->cancelTimerHandle == NULL)
    {
        return;
    }

    hmTime_stopTimer(appData->cancelTimerHandle);
    hmTime_destroyTimer(appData->cancelTimerHandle);
    appData->cancelTimerHandle = NULL;
}

static void startCalibrate(ScreenContext *mContext)
{
    AppData *appData = getScreenData(mContext, AppData);
    if (appData == NULL)
    {
        HLOG_E(TAG, "%s appData error", __func__);
        return;
    }
    getSportSaveHyroxManager()->handleHyroxServiceMessge(HYROX_SERVICE_MESSAGE_BEGIN);
    getScreenManager()->startScreenByFlag("hyroxSensorChooseScreen", FLAG_SCREEN_STANDAR, &appData->initData, sizeof(sportInitData));
}

static AlertDialog *getShowingDialog(ScreenContext *mContext)
{
    AlertDialog *mDialog = (AlertDialog *)findContainer(mContext, HYROX_FIRST_CONNECT_DIALOG);
    if (mDialog && mDialog->isShowing(mDialog))
    {
        return mDialog;
    }

    mDialog = (AlertDialog *)findContainer(mContext, HYROX_GOTO_CALIBARETE_DIALOG);
    if (mDialog && mDialog->isShowing(mDialog))
    {
        return mDialog;
    }

    return NULL;
}

static void dismissDialog(ScreenContext *mContext, const char *id)
{
    AlertDialog *mDialog = (AlertDialog *)findContainer(mContext, id);
    if (mDialog && mDialog->isShowing(mDialog))
    {
        mDialog->dismissDialog(mDialog);
