}

static void finishNoUserScreen(AppData *appData)
{
    if (appData == NULL)
    {
        HLOG_E(TAG, "%s appData error", __func__);
        return;
    }
    // 自定义配置下，需要删除自定义配置相关的屏幕
    if (getSportSaveHyroxManager()->hyroxIsCustomChoosed())
    {
        getScreenManager()->deleteScreenByName("hyroxSimulateChooseScreen");
        uint8_t hyroxArray[HYROX_RACE_MAX_COUNT] = {0};
        getSportSaveHyroxManager()->setCustomStations(hyroxArray, 0);
    }
    else if (appData->initData.type == SPORT_TYPE_HYROX_RACE)
    {
        getScreenManager()->deleteScreenByName("SportTypeInitItemSelectScreen");
    }
    getScreenManager()->deleteScreenByName("hyroxSimulateChooseScreen");
}

static void chooseWhichReadyGo(ScreenContext *mContext)
{
    AppData *appData = getScreenData(mContext, AppData);
    if (appData == NULL)
    {
        HLOG_E(TAG, "%s appData error", __func__);
        return;
    }
    finishNoUserScreen(appData);
    uint8_t flag = FLAG_SCREEN_REMOVE_CURRENT;
    switch (appData->initData.start_type)
    {
        case SPORT_START_TYPE_PHN:
        case SPORT_START_TYPE_PHN_RUNNING:
        {
            if (appData->initData.showPhnReady)
            {
                getScreenManager()->startScreenByFlag("PhnReadygoScreen", flag, NULL, 0);
            }
            else
            {
                getScreenManager()->startScreenByFlag("SportReadyGoScreen", flag, &appData->initData, sizeof(sportInitData));
            }
            return;
        }
        case SPORT_START_TYPE_RACE_STRATEGY:
            getScreenManager()->startScreenByFlag("SportHyroxRaceStrategyScreen", flag, &appData->initData, sizeof(sportInitData));
            return;
#if CFG_SPORT_HYROX_BLOCK_TEMPLATE && CFG_SPORT_HYROX_TRAINING_COUNTING
        case SPORT_START_TYPE_HYROX_BLOCK:
            getScreenManager()->startScreenByFlag("SportTrainingScreen", flag,
                                                   &appData->initData, sizeof(sportInitData));
            return;
#endif
        default:
            break;
    }
    getScreenManager()->startScreenByFlag("SportReadyGoScreen", flag, &appData->initData, sizeof(sportInitData));
}

static void backToHomeWithCancel(void)
{
    getSportSaveHyroxManager()->handleHyroxServiceMessge(HYROX_SERVICE_MESSAGE_CANCLE);
    ScreenManager_setHomeScreen("LauncherScreen");
    getScreenManager()->gotoHome();
    getSportsControlManager()->exitSport();
}

/**
 * @brief 跳过进入readyGo
 * @param mContext
 * @param self
 * @param type
 */
static void firstConnectDialog_cb(ScreenContext *mContext, AlertDialog *self, CapsuleBtnType type)
{
    getSportSaveHyroxManager()->handleHyroxServiceMessge(HYROX_SERVICE_MESSAGE_CANCLE);
    AppData *appData = getScreenData(mContext, AppData);
    if (appData && appData->initData.type == SPORT_TYPE_HYROX_TRAINING)
    {
        /*
         * HSP 已绑定但当前未连接时，跳过连接后每次都要求选择佩戴手。
         */
        if (hyroxTrainingHandleFirstConnectSkip(&appData->initData))
        {
            return;
        }
    }
