static void createFirstConnectStrapDialog(ScreenContext *mContext)
{
    AlertDialog *mDialog = (AlertDialog *)findContainer(mContext, HYROX_FIRST_CONNECT_DIALOG);
    if (mDialog)
    {
        mDialog->showDialog(mDialog);
        return;
    }

    mDialog = creatAlertDialog(mContext, SCREEN_NAME_FULL);
    if (mDialog == NULL)
    {
        HLOG_E(TAG, "%s create dialog fail", __func__);
        return;
    }

    mDialog->setImagePath(mDialog, HYROX_CONNECT_ANIM_FIRST_FRAME);
    mDialog->setTitleAndContent(mDialog, NULL, System_getLocaleText("id_hyrox_sim_connecting_hsp"));
    mDialog->addCapsuleButton(mDialog, System_getLocaleText("id_equipment_skip"));
    mDialog->setCapBtnAttr(mDialog, 0, CAP_BTN_ATTR_FOCUS_COLOR_V1, COMMON_BLUE_COLOR, NULL);
    mDialog->setCapsuleListener(mDialog, firstConnectDialog_cb);
    addContainer(mContext, HYROX_FIRST_CONNECT_DIALOG, mDialog);
    mDialog->showDialog(mDialog);
    mDialog->areaImgAnimCreate(mDialog, HYROX_CONNECT_ANIM_PATH, HYROX_CONNECT_ANIM_PREFIX,
                               HYROX_CONNECT_ANIM_EXT, HYROX_CONNECT_ANIM_FRAME_COUNT,
                               HYROX_CONNECT_ANIM_FPS, true, NULL, NULL);
}

static void createGotoCalibareteDialog(ScreenContext *mContext)
{
    dismissDialog(mContext, HYROX_FIRST_CONNECT_DIALOG);
    AlertDialog *mDialog = (AlertDialog *)findContainer(mContext, HYROX_GOTO_CALIBARETE_DIALOG);
    if (mDialog)
    {
        mDialog->showDialog(mDialog);
        return;
    }

    mDialog = creatAlertDialog(mContext, SCREEN_NAME_FULL);
    if (mDialog == NULL)
    {
        HLOG_E(TAG, "%s create dialog fail", __func__);
        return;
    }

    mDialog->setImagePath(mDialog, HYROX_CONNECT_ICON);
    mDialog->setTitleAndContent(mDialog, NULL, System_getLocaleText("id_hyrox_sim_connected_hsp_calibrate"));
    mDialog->addCapsuleButton(mDialog, System_getLocaleText("id_hyrox_sim_calibrate"));
    mDialog->setCapBtnAttr(mDialog, 0, CAP_BTN_ATTR_FOCUS_COLOR_V1, COMMON_BLUE_COLOR, NULL);
    mDialog->setCapsuleListener(mDialog, gotoCalibareteDialog_cb);
    addContainer(mContext, HYROX_GOTO_CALIBARETE_DIALOG, mDialog);
    mDialog->showDialog(mDialog);
}

