/**
 * 获取当前 HSP 是否支持自动校准，2.1.0.2 版本以上才支持。
 */
static bool _getHelioMotionSfVersion(void)
{
#ifdef CFG_SUPPORT_SPORT_PERIPHERAL
    ble_peripheral_dev_info_t dev_info = {0};
    const ble_peripheral_sys_interface *ble_if = getBlePeripheralSysIf();
    unsigned int major;
    unsigned int minor;
    unsigned int patch;
    unsigned int build;

    if (ble_if == NULL || ble_if->get_device_binded == NULL ||
        !ble_if->get_device_binded(BLE_PERIPHERAL_TYPE_AMAZFIT_IMU_SENSOR, 0, &dev_info))
    {
        return false;
    }

    if (dev_info.dev_record.dev.type != BLE_PERIPHERAL_TYPE_AMAZFIT_IMU_SENSOR ||
        strcmp(dev_info.dev_record.dev.device_name, "Helio Core Motion") != 0 ||
        sscanf(dev_info.dev_record.soft_version, "%u.%u.%u.%u", &major, &minor, &patch, &build) != 4)
    {
        return false;
    }

    return major > 2 ||
           (major == 2 &&
            (minor > 1 ||
             (minor == 1 &&
              (patch > 0 || (patch == 0 && build >= 2)))));
#endif
    return false;
}

/* 自动校准提示仅用于 HYROX Race 与非自定义 HYROX Simulation。 */
static bool _hyroxSupportAutoCalibration(sport_type_t sportType)
{
    bool result = false;
    if (sportType == SPORT_TYPE_HYROX_RACE ||
       (sportType == SPORT_TYPE_HYROX_SIMULATION && gHyroxSource != HYROX_FROM_SIM_CUSTOM))
    {
         result = _getHelioMotionSfVersion();
    }
    return result;
}

/**
 * @brief 判断是否需要显示动态校准提醒对话框。
 *        运动支持自动校准、传感器已连接且尚未校准成功时返回 true。
