/**
 * @brief 进入校准等待窗口，只有 CALIBRATE 到 START 前的算法上报可信。
 */
static void _begin_calib_wait(void)
{
    sCurrentCalibDone = HYROX_SIMULATION_CALIB_UNDONE;
    sSummary.calib_done = HYROX_SIMULATION_CALIB_UNDONE;
    sCalibPhase = HYROX_CALIB_PHASE_WAIT_START;
}

/**
 * @brief 缓存算法上报的校准状态：静态校准仅 START 前更新；动态校准仅首站运动中/暂停更新。
 */
static void _update_calib_before_start(uint8_t calib_done)
{
    if (sCalibPhase == HYROX_CALIB_PHASE_IDLE) {
        return;
    }

    bool supportAutoCalib = getSportSaveHyroxManager()->hyroxSupportAutoCalibration(
        SportContrlService_getOps()->getSportType());
    SportStateType mState = SportContrlService_getOps()->getSportState();
    if (supportAutoCalib) {
        if (getSportSaveHyroxManager()->getHyroxCurIndex(NULL) != 0 ||
            (mState != SPORT_STATE_RUN && mState != SPORT_STATE_SUSPEND)) {
            return;
        }
    } else if (sCalibPhase != HYROX_CALIB_PHASE_WAIT_START) {
        return;
    }

    if (sCurrentCalibDone != (hyrox_simulation_calib_state_t)calib_done) {
        HLOG_I(TAG, "calib update before start: %u", (unsigned)calib_done);
    }
    sCurrentCalibDone = (hyrox_simulation_calib_state_t)calib_done;
    sSummary.calib_done = (hyrox_simulation_calib_state_t)calib_done;
    if (!gHasShowToasted && sCurrentCalibDone == HYROX_SIMULATION_CALIB_SUCCESS &&
        (supportAutoCalib || mState == SPORT_STATE_PRESTART))
    {
        gHasShowToasted = getSportsScreenPresenter()->showCalibSuccessReminder();
    }
}

/** 动态校准成功只启用 HTE，不重置已运行站点的缓存和时间窗。 */
static void _try_enable_dynamic_hte(void)
{
    if (sCurrentCalibDone != HYROX_SIMULATION_CALIB_SUCCESS ||
        sRuntimeMode != HYROX_RUNTIME_MODE_HT_ONLY ||
        !sRuntimeCacheReady ||
        !getSportSaveHyroxManager()->hyroxSupportAutoCalibration(
            SportContrlService_getOps()->getSportType())) {
        return;
    }

    sRuntimeMode = HYROX_RUNTIME_MODE_FULL;
    HLOG_I(TAG, "dynamic calib success");
}

/**
 * @brief START 时锁定校准状态；未发起校准则保持 UNDONE。
 */
static void _lock_calib_on_start(void)
{
    if (sCalibPhase != HYROX_CALIB_PHASE_WAIT_START) {
        sCurrentCalibDone = HYROX_SIMULATION_CALIB_UNDONE;
    }
    sSummary.calib_done = sCurrentCalibDone;
    sCalibPhase = HYROX_CALIB_PHASE_LOCKED;
    HLOG_I(TAG, "calib locked: %u", (unsigned)sCurrentCalibDone);
}

/**
 * @brief 判断当前站点是否允许产出 ALG2 负荷、insight 和 REP detail。
 */
static bool _is_calib_success(void)
{
#if HMI_COMP_MONKEY
    if (sMockAlg2InputEnabled) {
        return true;
    }
    if (!sRuntimeCacheReady) {
        return;
    }
    _cache_free();
    memset(&sCache, 0, sizeof(sCache));
    sRuntimeCacheReady = false;
}

/**
 * @brief 判断当前模式是否需要运行 HT engine 和接收 HT 状态。
 */
static bool _should_run_ht(void)
{
    return (sRuntimeMode != HYROX_RUNTIME_MODE_NONE) && ht_engine_is_enabled();
}

/**
 * @brief 判断当前模式是否具备 HTE 缓存、ALG2 和评价 detail 全链路能力。
 */
static bool _should_run_hte(void)
{
    /* FULL 仅在 engine、校准和 HTE cache 均就绪后设置。 */
    return sRuntimeMode == HYROX_RUNTIME_MODE_FULL;
}

/**
 * @brief 选择本次运动 runtime 模式；自动换项接入后只需扩展此处的失败降级策略。
 */
static hyrox_runtime_mode_t _select_runtime_mode(void)
{
    bool autoCalibrate = getSportSaveHyroxManager()->hyroxSupportAutoCalibration(
            SportContrlService_getOps()->getSportType());

    /* 自动校准结果在 START 后才可能到达，PRESTART 必须先保留 cache。 */
    if (autoCalibrate && !_is_calib_success()) {
        return HYROX_RUNTIME_MODE_HT_ONLY;
    }

    /* Sensor 校准成功时启用完整 HT + HTE 链路。 */
    if (_is_calib_success()) {
        return HYROX_RUNTIME_MODE_FULL;
    }

    /* 未校准但支持自动换项时，仅启用 HT。 */
    // if (_support_auto_switch()) {
    //     return HYROX_RUNTIME_MODE_HT_ONLY;
    // }

    return HYROX_RUNTIME_MODE_NONE;
}

/**
 * @brief 统一切换 HT/HTE 运行资源，保证 engine 和 HTE cache 与模式一致。
 */
static int _apply_runtime_mode(hyrox_runtime_mode_t mode)
{
    if (mode > HYROX_RUNTIME_MODE_FULL) {
        HLOG_E(TAG, "invalid runtime mode=%u", (unsigned)mode);
        return -1;
    }

    if (mode == HYROX_RUNTIME_MODE_NONE) {
        if (ht_engine_is_enabled() && hybrid_training_disable_mode() != 0) {
            HLOG_E(TAG, "runtime mode NONE: disable engine failed");
            return -1;
        }
        _hyrox_runtime_cache_deinit();
        sRuntimeMode = mode;
        HLOG_I(TAG, "runtime mode=%u ht=0 hte=0", (unsigned)mode);
        return 0;
    }

    if (!ht_engine_is_enabled() && hybrid_training_enable_mode() != 0) {
        HLOG_E(TAG, "runtime mode=%u: enable engine failed", (unsigned)mode);
        return -1;
    }

    if (mode == HYROX_RUNTIME_MODE_FULL) {
        if (!_is_calib_success() || _hyrox_runtime_cache_init() != 0) {
            HLOG_E(TAG, "runtime mode FULL: calib/cache unavailable");
            hybrid_training_disable_mode();
            _hyrox_runtime_cache_deinit();
            sRuntimeMode = HYROX_RUNTIME_MODE_NONE;
            return -1;
        }
    } else if (getSportSaveHyroxManager()->hyroxSupportAutoCalibration(
                   SportContrlService_getOps()->getSportType())) {
        if (_hyrox_runtime_cache_init() != 0) {
            HLOG_E(TAG, "runtime mode HT_ONLY: cache init failed");
            hybrid_training_disable_mode();
            sRuntimeMode = HYROX_RUNTIME_MODE_NONE;
            return -1;
        }
    } else {
        _hyrox_runtime_cache_deinit();
    }

    sRuntimeMode = mode;
    HLOG_I(TAG,
           "runtime mode=%u ht=1 hte=%u",
           (unsigned)mode,
           (unsigned)(mode == HYROX_RUNTIME_MODE_FULL));
    return 0;
}

